import React, { useState, useEffect } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import RideCard from '../components/RideCard';
import { useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import { FaMapMarkerAlt, FaCalendarAlt, FaClock } from 'react-icons/fa';
import { toast } from 'react-toastify';

const UserDashboard = () => {
  const { isAuthenticated, user } = useSelector((state) => state.auth);
  const navigate = useNavigate();
  const [rides, setRides] = useState([]);
  const [stats, setStats] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!isAuthenticated) {
      navigate('/login');
      return;
    }

    fetchDashboardData();
  }, [isAuthenticated, navigate]);

  const fetchDashboardData = async () => {
    try {
      const ridesRes = await api.get('/users/rides?limit=5');
      const statsRes = await api.get('/users/ride-stats');

      setRides(ridesRes.data.rides || []);
      setStats(statsRes.data.stats || {});
    } catch (error) {
      toast.error('Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col">
        <Header />
        <div className="flex-1 flex items-center justify-center">
          <p>Loading...</p>
        </div>
        <Footer />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-gray-50">
      <Header />

      <main className="flex-1 p-4 sm:p-6 lg:p-8">
        <div className="max-w-7xl mx-auto">
          {/* Welcome Section */}
          <div className="bg-gradient-to-r from-blue-600 to-blue-800 text-white rounded-lg p-6 mb-8">
            <h1 className="text-3xl font-bold mb-2">Welcome, {user?.fullName}!</h1>
            <p className="text-blue-100">Ready for your next ride?</p>
          </div>

          {/* Stats Section */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
            {[
              { label: 'Total Rides', value: stats.totalRides || 0, icon: '🚗' },
              { label: 'Completed', value: stats.completedRides || 0, icon: '✅' },
              { label: 'Total Spent', value: `₹${stats.totalSpent || 0}`, icon: '💰' },
              { label: 'Rating', value: `${stats.averageRating || 0}/5`, icon: '⭐' },
            ].map((stat, index) => (
              <div key={index} className="bg-white rounded-lg p-4 shadow-md">
                <p className="text-3xl mb-2">{stat.icon}</p>
                <p className="text-gray-600 text-sm">{stat.label}</p>
                <p className="text-2xl font-bold text-gray-800">{stat.value}</p>
              </div>
            ))}
          </div>

          {/* Action Buttons */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
            <button
              onClick={() => navigate('/ride-booking')}
              className="bg-blue-600 text-white py-3 rounded-lg hover:bg-blue-700 font-bold transition"
            >
              Book a Ride
            </button>
            <button
              onClick={() => navigate('/wallet')}
              className="bg-green-600 text-white py-3 rounded-lg hover:bg-green-700 font-bold transition"
            >
              My Wallet
            </button>
            <button
              onClick={() => navigate('/profile')}
              className="bg-purple-600 text-white py-3 rounded-lg hover:bg-purple-700 font-bold transition"
            >
              My Profile
            </button>
          </div>

          {/* Recent Rides */}
          <div className="bg-white rounded-lg shadow-md p-6">
            <h2 className="text-2xl font-bold mb-6">Recent Rides</h2>
            {rides.length === 0 ? (
              <p className="text-gray-600 text-center py-8">No rides yet. Book your first ride!</p>
            ) : (
              <div className="space-y-4">
                {rides.map((ride) => (
                  <RideCard key={ride._id} ride={ride} />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      <Footer />
    </div>
  );
};

export default UserDashboard;
